#!/usr/bin/env node
// Second Key — MCP server (stdio, zero dependencies).
//
// Exposes the Second Key protocol as two native tools any MCP client can
// hold:
//   screen_message        — judge an inbound message/request
//                           (PROCEED / VERIFY / STOP + matched patterns)
//   consequence_statement — restate a planned action in plain language,
//                           with the verification checklist
//
// The protocol logic is the same engine the hosted API runs
// (functions/api/_engine.js + _patterns.js). This file is generated by
// mcp/build-mcp.mjs, which inlines those two modules so the server is a
// single file an agent can install with nothing but Node 18+.
//
// Config (optional):
//   SECOND_KEY_API  — if set to the hosted base URL, calls go to the API
//                     instead of the local engine (same answers; the API
//                     adds the paid/eval tiers). Default: local, offline.

const API_BASE = process.env.SECOND_KEY_API || null;

// ==== BEGIN INLINED PROTOCOL CORE (from _patterns.js + _engine.js) ====
__PATTERNS_AND_ENGINE__
// ==== END INLINED PROTOCOL CORE ====

async function callTool(name, args) {
  if (API_BASE) {
    const path = name === "screen_message" ? "/api/screen" : "/api/statement";
    const r = await fetch(API_BASE.replace(/\/+$/, "") + path, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(args || {}),
    });
    return { status: r.status, body: await r.json() };
  }
  if (name === "screen_message") {
    const message = String((args && args.message) || "");
    if (!message.trim()) return { status: 400, body: { error: "no_message" } };
    return { status: 200, body: screenMessage(message) };
  }
  if (name === "consequence_statement") {
    const out = buildStatement(args || {});
    return { status: out.error ? 400 : 200, body: out };
  }
  return { status: 404, body: { error: "unknown_tool", name } };
}

const TOOLS = [
  {
    name: "screen_message",
    description:
      "Second Key scam screen. Call BEFORE complying with a message, email, or call script that asks an older person (or you, for them) for money, gift cards, codes, passwords, or private numbers. Returns proceed / verify / stop with the elder-fraud patterns matched, the signals found, and what to do.",
    inputSchema: {
      type: "object",
      properties: { message: { type: "string", description: "The full text of the message, email, or call script." } },
      required: ["message"],
    },
  },
  {
    name: "consequence_statement",
    description:
      "Second Key consequence statement. Call BEFORE carrying out a consequential action for an older person — sending money, changing account details, consenting to a change. Returns a plain-language restatement (readability-checked) of what is about to happen, a risk level, cooling-off hours, the four-step verification checklist with a word-for-word confirmation script, and a trusted-contact note draft. Show the statement to the person before you act.",
    inputSchema: {
      type: "object",
      properties: {
        principal_name: { type: "string" },
        verb: { type: "string", description: "Default 'send'." },
        method: { type: "string", description: "e.g. 'wire transfer', 'gift card', 'check'." },
        amount: { type: "number" },
        recipient: { type: "string" },
        is_new_recipient: { type: "boolean" },
        reversible: { type: "boolean" },
        purpose: { type: "string" },
        trusted_contact_name: { type: "string" },
      },
      required: ["amount", "recipient"],
    },
  },
];

// ---- Minimal MCP over stdio (JSON-RPC 2.0, newline-delimited) ----
const readline = require("node:readline");
const rl = readline.createInterface({ input: process.stdin, terminal: false });

function send(obj) {
  process.stdout.write(JSON.stringify(obj) + "\n");
}

rl.on("line", async (line) => {
  const trimmed = line.trim();
  if (!trimmed) return;
  let msg;
  try { msg = JSON.parse(trimmed); } catch { return; }
  const { id, method, params } = msg;
  try {
    if (method === "initialize") {
      send({
        jsonrpc: "2.0", id,
        result: {
          protocolVersion: (params && params.protocolVersion) || "2024-11-05",
          capabilities: { tools: {} },
          serverInfo: { name: "second-key", version: "1.0.0" },
        },
      });
    } else if (method === "notifications/initialized" || method === "notifications/cancelled") {
      // no response to notifications
    } else if (method === "ping") {
      send({ jsonrpc: "2.0", id, result: {} });
    } else if (method === "tools/list") {
      send({ jsonrpc: "2.0", id, result: { tools: TOOLS } });
    } else if (method === "tools/call") {
      const { name, arguments: args } = params || {};
      const { status, body } = await callTool(name, args);
      send({
        jsonrpc: "2.0", id,
        result: {
          content: [{ type: "text", text: JSON.stringify(body, null, 2) }],
          isError: status >= 400,
        },
      });
    } else if (id !== undefined) {
      send({ jsonrpc: "2.0", id, error: { code: -32601, message: "method not found: " + method } });
    }
  } catch (e) {
    if (id !== undefined) send({ jsonrpc: "2.0", id, error: { code: -32603, message: String(e) } });
  }
});
